// Failed executions are logged here and reported to Convex, where admins see them.
const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
const { workflow = {}, execution = {} } = $input.first().json;
const report = {
  workflow: workflow.name || 'unknown workflow',
  node: execution.lastNodeExecuted || undefined,
  message: (execution.error && execution.error.message) || 'Unknown error',
  executionId: execution.id ? String(execution.id) : undefined,
};
console.error(`[LendLoop] workflow failed: ${report.workflow} at ${report.node}: ${report.message}`);
const path = '/n8n/automation-error';
const body = JSON.stringify(report);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.POST.${path}.${body}`).digest('hex');
return [{ json: { body, headers: { 'Content-Type': 'application/json', 'X-LendLoop-Timestamp': timestamp, 'X-LendLoop-Signature': signature } } }];
